{
  "name": "opencode-claude-subscription",
  "version": "0.1.4",
  "description": "OpenCode v2 plugin: use your Claude Pro/Max subscription with OpenCode's built-in Anthropic provider.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "anthropic",
    "claude",
    "claude-code",
    "claude-max",
    "claude-pro",
    "oauth",
    "subscription"
  ],
  "license": "MIT",
  "author": "eysenfalk",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/eysenfalk/opencode-claude-subscription.git"
  },
  "homepage": "https://github.com/eysenfalk/opencode-claude-subscription#readme",
  "bugs": {
    "url": "https://github.com/eysenfalk/opencode-claude-subscription/issues"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": "./src/index.ts"
  },
  "files": [
    "dist",
    "src",
    "server.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.build.json",
    "typecheck": "tsc --noEmit",
    "test": "node --test 'test/**/*.test.ts'",
    "prepublishOnly": "npm run typecheck && npm test && npm run build"
  },
  "engines": {
    "node": ">=24"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.18",
    "@types/node": "^26.6.3",
    "typescript": "^5.9.0"
  }
}
